void MX_ADC1_Init(void){ADC_ChannelConfTypeDef c={0};hadc1.Instance=ADC1;hadc1.Init.ClockPrescaler=ADC_CLOCK_SYNC_PCLK_DIV4;hadc1.Init.Resolution=ADC_RESOLUTION_12B;hadc1.Init.ScanConvMode=DISABLE;hadc1.Init.ContinuousConvMode=DISABLE;hadc1.Init.DiscontinuousConvMode=DISABLE;hadc1.Init.ExternalTrigConvEdge=ADC_EXTERNALTRIGCONVEDGE_NONE;hadc1.Init.ExternalTrigConv=ADC_SOFTWARE_START;hadc1.Init.DataAlign=ADC_DATAALIGN_RIGHT;hadc1.Init.NbrOfConversion=1;hadc1.Init.DMAContinuousRequests=DISABLE;hadc1.Init.EOCSelection=ADC_EOC_SINGLE_CONV;if(HAL_ADC_Init(&hadc1)!=HAL_OK)Error_Handler();c.Channel=ADC_CHANNEL_0;c.Rank=1;c.SamplingTime=ADC_SAMPLETIME_84CYCLES;if(HAL_ADC_ConfigChannel(&hadc1,&c)!=HAL_OK)Error_Handler();}
